import { endpoint } from '@core/utils';
import { buildContactMessage } from '@app/data';
import { expect, test } from '@app/fixtures';

// Planned and first generated by the Playwright test agents, then reviewed and
// rewritten onto the page objects; see docs/ai-assisted-testing.md.

test.describe('Contact form (guest)', { tag: '@regression' }, () => {
  test.beforeEach(async ({ contactPage }) => {
    await contactPage.goto();
  });

  test('sending an empty form flags every required field', async ({ contactPage }) => {
    await test.step('submit the empty form', async () => {
      await contactPage.send();

      await expect(contactPage.firstNameError).toHaveText('First name is required');
      await expect(contactPage.lastNameError).toHaveText('Last name is required');
      await expect(contactPage.emailError).toHaveText('Email is required');
      await expect(contactPage.subjectError).toHaveText('Subject is required');
      await expect(contactPage.messageError).toHaveText('Message is required');
    });

    await test.step('filling one field clears only its error', async () => {
      await contactPage.firstName.fill('Jane');
      await contactPage.send();

      await expect(contactPage.firstNameError).toBeHidden();
      await expect(contactPage.lastNameError).toBeVisible();
      await expect(contactPage.messageError).toBeVisible();
      await expect(contactPage.confirmation).toBeHidden();
    });
  });

  test('an invalid email is rejected', async ({ contactPage }) => {
    await contactPage.fillForm(buildContactMessage({ email: 'not-an-email' }));
    await contactPage.send();

    await expect(contactPage.emailError).toHaveText('Email format is invalid');
    await expect(contactPage.confirmation).toBeHidden();
  });

  test('the message must be at least 50 characters', async ({ contactPage }, testInfo) => {
    testInfo.annotations.push({
      type: 'ux-gap',
      description:
        'The message is validated on blur and its error box moves the Send button, so clicking ' +
        'Send straight after typing can miss it; the page object blurs the field first.',
    });
    await contactPage.fillForm(buildContactMessage({ message: 'a'.repeat(49) }));
    await contactPage.send();
    await expect(contactPage.messageError).toHaveText('Message must be minimal 50 characters');

    await contactPage.enterMessage('a'.repeat(50));

    await expect(contactPage.messageError).toBeHidden();
  });

  test('a valid message is sent and confirmed', async ({ page, config, contactPage }, testInfo) => {
    // Toolshop has no API to delete contact messages.
    testInfo.annotations.push({
      type: 'retained-data',
      description: 'contact messages cannot be deleted through the API',
    });
    const sent = page.waitForResponse(
      (response) =>
        endpoint(config.apiUrl, '/messages')(new URL(response.url())) &&
        response.request().method() === 'POST',
    );

    await contactPage.fillForm(buildContactMessage());
    await contactPage.send();

    expect((await sent).ok()).toBe(true);
    await expect(contactPage.confirmation).toHaveText(
      'Thanks for your message! We will contact you shortly.',
    );
    await expect(contactPage.sendButton).toBeHidden();
  });
});
